use vstd::prelude::*;

verus! {
    // Specification for the solve function
    fn solve(stdin_input: Vec<char>) -> (result: Vec<char>)
        requires
            stdin_input.len() >= 3, // Ensure there are at least 3 characters
            // Ensure the first and second characters are valid for comparison
            stdin_input[0] != '\0' && stdin_input[2] != '\0',
        ensures
            result.len() == 2, // The result should contain exactly 2 characters
            (result[0] == '<' || result[0] == '>' || result[0] == '='),
            result[1] == '\n', // The second character should be a newline
    {
        // Extract the first and second characters from the input
        let first = stdin_input[0];
        let second = stdin_input[2]; // The space is at index 1

        // Prepare the result vector
        let mut result = Vec::new();

        // Compare the two characters
        if first < second {
            result.push('<');
        } else if first > second {
            result.push('>');
        } else {
            result.push('=');
        }

        // Add the newline character
        result.push('\n');

        result
    }
}

